mapper.insert:
INSERT INTO vehicle_odometer(vehicle_id,odometer_km,measured_at)
VALUES(#{id},#{input.odometerKm},#{input.measuredAt})
ON DUPLICATE KEY UPDATE odometer_km=#{input.odometerKm},measured_at=#{input.measuredAt}

mapper.update:
UPDATE vehicle_maintenance_plan SET next_date=#{nextDate},next_odometer_km=#{nextKm},cycle=cycle+1,
    last_service_date=#{input.date},last_service_odometer_km=#{input.odometerKm}
WHERE id=#{id} AND enabled=1 AND cycle=#{input.cycle}

UPDATE vehicle_repair SET status=#{input.status},assignee=COALESCE(#{input.assignee},assignee),
    repair_shop=COALESCE(#{input.shop},repair_shop),cost=COALESCE(#{input.cost},cost),updated_at=#{now},
    completed_on=CASE WHEN #{input.status}='DONE' THEN #{input.completedOn} ELSE completed_on END,
    completed_odometer_km=CASE WHEN #{input.status}='DONE' THEN #{input.completedOdometerKm} ELSE completed_odometer_km END,
    maintenance_cycle_applied=#{appliedCycle}
WHERE id=#{id} AND status=#{expected}

mapper.select:
WITH active_fuel AS (
    SELECT f.* FROM fuel_record f JOIN vehicle v ON v.id=f.vehicle_id
    WHERE v.fleet_id=#{fleetId} AND v.vehicle_type=#{model} AND v.id<>#{vehicleId}
      AND f.fueled_at<#{end} AND f.active_marker=1
)

SELECT COUNT(liters_per_100_km) AS samples, AVG(liters_per_100_km) AS average
FROM intervals WHERE fueled_at>=#{start}
